func:
const frame = msg.payload || msg;
const canId = frame.canid;
const data = frame.data || [];

if (canId < 0x351 || canId > 0x35E) {
    return null;
}

let state = flow.get("pylontech") || {
    kind: "PylontechCanState",
    version: 1
};

function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function s16(buf, offset) {
    var val = u16(buf, offset);
    return val > 0x7FFF ? val - 0x10000 : val;
}

switch (canId) {
    case 0x351:
        state.chargeVoltageV = u16(data, 0) * 0.1;
        state.chargeCurrentLimitA = s16(data, 2) * 0.1;
        state.dischargeCurrentLimitA = s16(data, 4) * 0.1;
        break;
    case 0x355:
        state.socPercent = u16(data, 0);
        state.sohPercent = u16(data, 2);
        break;
    case 0x356:
        state.voltageV = s16(data, 0) * 0.01;
        state.currentA = s16(data, 2) * 0.1;
        state.temperatureC = s16(data, 4) * 0.1;
        break;
    case 0x359:
        state.moduleCount = data[4];
        var prot1 = data[0];
        var prot2 = data[1];
        var alarm1 = data[2];
        var alarm2 = data[3];
        state.protection = {
            cellOverVoltage: !!(prot1 & 0x02),
            cellUnderVoltage: !!(prot1 & 0x04),
            cellOverTemperature: !!(prot1 & 0x08),
            cellUnderTemperature: !!(prot1 & 0x10),
            dischargeOverCurrent: !!(prot1 & 0x80),
            chargeOverCurrent: !!(prot2 & 0x01),
            systemError: !!(prot2 & 0x08)
        };
        state.alarm = {
            cellHighVoltage: !!(alarm1 & 0x02),
            cellLowVoltage: !!(alarm1 & 0x04),
            cellHighTemperature: !!(alarm1 & 0x08),
            cellLowTemperature: !!(alarm1 & 0x10),
            dischargeHighCurrent: !!(alarm1 & 0x80),
            chargeHighCurrent: !!(alarm2 & 0x01),
            internalCommFail: !!(alarm2 & 0x08)
        };
        break;
    case 0x35C:
        var flags = data[0];
        state.request = {
            chargeEnable: !!(flags & 0x80),
            dischargeEnable: !!(flags & 0x40),
            forceChargeI: !!(flags & 0x20),
            forceChargeII: !!(flags & 0x10),
            fullCharge: !!(flags & 0x08)
        };
        break;
    case 0x35E:
        var name = "";
        for (var i = 0; i < 8; i++) {
            if (data[i] === 0) break;
            name += String.fromCharCode(data[i]);
        }
        state.manufacturerName = name;
        break;
    default:
        return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("pylontech", state);
msg.payload = state;
return msg;

var state = flow.get("pylontech");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
